}

SELECT ?zone ?zname ?point WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?zname .
  ?point ref:hasInput ?zone .
  ?point a brick:Air_Temperature .
}

SELECT ?sensor ?point ?zone WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?point }
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label ?zone_name .
}

SELECT DISTINCT ?zone ?zname WHERE {
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label ?zname .
  ?sensor a brick:Zone_Air_Temperature_Sensor ; ref:isLocationOf ?zone .
}

